// Picks the invoices that have just reached a reminder stage and have not been chased for it yet.
const s = $('Settings').first().json;
const stages = String(s.reminderDays).split(',').map(n => parseInt(n, 10)).filter(n => n > 0).sort((a, b) => a - b);
const store = $getWorkflowStaticData('global');   // remembers sent reminders between runs (active workflows only)
store.sent = store.sent || {};

// Xero returns dates as "2026-08-01T00:00:00" (DueDateString) or "/Date(1785542400000+0000)/" (DueDate)
function xeroDate(inv) {
  if (inv.DueDateString) return new Date(inv.DueDateString.slice(0, 10) + 'T00:00:00Z');
  const m = String(inv.DueDate || '').match(/\/Date\((\d+)/);
  return m ? new Date(parseInt(m[1], 10)) : null;
}
// Today's date in Singapore, as a UTC midnight so the day count is exact
const sg = new Intl.DateTimeFormat('en-CA', { timeZone: s.timezone || 'Asia/Singapore' }).format(new Date());
const today = new Date(sg + 'T00:00:00Z');

const out = [];
for (const item of $input.all()) {
  const inv = item.json;
  if (inv.Type && inv.Type !== 'ACCREC') continue;        // sales invoices only
  if (!(Number(inv.AmountDue) > 0)) continue;              // fully paid or credited
  if (/^HOLD/i.test(inv.Reference || '')) continue;        // disputed or agreed: put HOLD at the start of the Reference
  const due = xeroDate(inv);
  if (!due) continue;
  const daysOverdue = Math.round((today - due) / 86400000);
  const reached = stages.filter(d => daysOverdue >= d);
  if (!reached.length) continue;
  const stage = reached[reached.length - 1];
  const key = inv.InvoiceID + ':' + stage;
  if (store.sent[key]) continue;                           // already chased at this stage
  out.push({ json: {
    key,
    invoiceId: inv.InvoiceID,
    invoiceNumber: inv.InvoiceNumber,
    reference: inv.Reference || '',
    contactId: inv.Contact && inv.Contact.ContactID,
    contactName: inv.Contact && inv.Contact.Name,
    currency: inv.CurrencyCode || 'SGD',
    amountDue: Number(inv.AmountDue),
    dueDate: due.toISOString().slice(0, 10),
    daysOverdue,
    stage,
    stageNumber: stages.indexOf(stage) + 1,
    finalStage: stage === stages[stages.length - 1],
  }});
}
return out;

// Writes the reminder. Tone gets firmer at each stage; the last stage copies the owner.
const s = $('Settings').first().json;
const inv = $('Pick invoices due a reminder').item.json;
const contact = $json;
const email = contact.EmailAddress || '';
const money = inv.currency + ' ' + inv.amountDue.toLocaleString('en-SG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const first = (contact.FirstName || '').trim();
const hello = first ? 'Hi ' + first + ',' : 'Hello,';
const ref = inv.reference ? ' (your ref ' + inv.reference + ')' : '';

const templates = {
  1: {
    subject: `Friendly reminder: invoice ${inv.invoiceNumber} is past due`,
    body: `${hello}\n\nA quick reminder that invoice ${inv.invoiceNumber}${ref} for ${money} was due on ${inv.dueDate}. It may simply have slipped through, so I have put the payment details below.\n\n${s.paymentDetails}\n\nIf it has already been paid, please ignore this note, and thank you.\n\nBest regards,\n${s.senderName}\n${s.companyName}`,
  },
  2: {
    subject: `Second reminder: invoice ${inv.invoiceNumber}, ${money} outstanding`,
    body: `${hello}\n\nInvoice ${inv.invoiceNumber}${ref} for ${money} is now ${inv.daysOverdue} days overdue (due ${inv.dueDate}). Could you let me know when we can expect payment? If there is a problem with the invoice or the delivery, reply to this email and we will sort it out.\n\n${s.paymentDetails}\n\nThank you,\n${s.senderName}\n${s.companyName}`,
  },
  3: {
    subject: `Final reminder: invoice ${inv.invoiceNumber} is ${inv.daysOverdue} days overdue`,
    body: `${hello}\n\nInvoice ${inv.invoiceNumber}${ref} for ${money} is now ${inv.daysOverdue} days overdue. Please arrange payment this week, or reply with a date we can expect it. I have copied ${s.ownerName} so we can resolve this quickly.\n\n${s.paymentDetails}\n\nRegards,\n${s.senderName}\n${s.companyName}`,
  },
};
const t = templates[inv.finalStage ? 3 : Math.min(inv.stageNumber, 2)];

return {
  json: {
    key: inv.key,
    to: email || s.ownerEmail,
    cc: inv.finalStage && email ? s.ownerEmail : '',
    subject: email ? t.subject : `[No email on file for ${inv.contactName}] ${t.subject}`,
    body: t.body,
    invoiceNumber: inv.invoiceNumber,
    contactName: inv.contactName,
    amountDue: inv.amountDue,
    currency: inv.currency,
    daysOverdue: inv.daysOverdue,
    stage: inv.stage,
  },
};

// Marks each reminder as sent (so it never goes twice) and builds one summary for the owner.
const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const sentOn = new Date().toISOString().slice(0, 10);
const rows = $('Write the reminder').all().map(i => i.json);
for (const r of rows) store.sent[r.key] = sentOn;

// Housekeeping: forget entries older than 400 days
for (const [k, d] of Object.entries(store.sent)) {
  if ((Date.now() - new Date(d)) / 86400000 > 400) delete store.sent[k];
}

const totals = {};
for (const r of rows) totals[r.currency] = (totals[r.currency] || 0) + r.amountDue;
const lines = rows.map(r => `- ${r.contactName}: ${r.invoiceNumber}, ${r.currency} ${r.amountDue.toFixed(2)}, ${r.daysOverdue} days overdue (${r.stage}-day reminder)`);
const totalText = Object.entries(totals).map(([c, v]) => `${c} ${v.toFixed(2)}`).join(' + ');
return [{ json: {
  count: rows.length,
  subject: `Payment reminders sent today: ${rows.length} invoices, ${totalText}`,
  body: `Reminders sent this morning:\n\n${lines.join('\n')}\n\nTotal chased: ${totalText}.\nThis summary is sent by your overdue-invoice automation.`,
}}];
